import { expect, test } from '@playwright/test';

/** Wait until the application has drawn a real page; the assertions after it wait on their own, so a page without the marker (an error page) is not an error here. */
async function ready(page) {
  await page.locator('main[data-page]:not([data-page="loading"])').waitFor({ timeout: 5_000 }).catch(() => {});
}

// A live binding makes the open screen refetch its view (GET /api/view?path=<screen path>).
const views = [];
const marks = new Map();
const watch = (page) => page.on('response', (r) => {
  if (r.url().includes('/api/view')) views.push({ page, path: new URL(r.url()).searchParams.get('path') });
});
const refreshes = (page) => views.filter((v) => v.page === page && v.path === new URL(page.url()).pathname).length;

async function newSession(browser, baseURL, viewport) {
  const context = await browser.newContext({ baseURL, viewport });
  return { context, page: await context.newPage(), response: null };
}

// Verifies: R-11
test("a reader sees a published essay without reloading", async ({ browser, baseURL, page: firstPage, context: firstContext }) => {
  const sessions = {};
  sessions["reader"] = { context: firstContext, page: firstPage, response: null };
  sessions["author"] = await newSession(browser, baseURL, firstPage.viewportSize());
  for (const s of Object.values(sessions)) watch(s.page);
  let current = sessions["reader"];
  let { context, page, response } = current;
  try {
    response = await page.goto("/");
    await ready(page);
    marks.set(page, refreshes(page));
    marks.set(page, refreshes(page));
    current.response = response;
    current = sessions["author"];
    ({ context, page, response } = current);
    response = await page.goto("/posts/on-sharpening");
    await ready(page);
    marks.set(page, refreshes(page));
    expect(response.status()).toBe(200);
    marks.set(page, refreshes(page));
    current.response = response;
    current = sessions["reader"];
    ({ context, page, response } = current);
    await expect.poll(() => refreshes(page), { message: 'the open screen refetches its view' }).toBeGreaterThan(marks.get(page) ?? 0);
    marks.set(page, refreshes(page));
    await expect(page.getByText("On Sharpening").first()).toBeVisible();
  } finally {
    for (const s of Object.values(sessions)) {
      if (s.context !== firstContext) await s.context.close();
    }
  }
});
